from django.db import migrations, models


def to_queues(apps, schema_editor):
    """A channel's old play order (its playlist, or the whole library) becomes its queue, at the same song."""
    AudioChannel = apps.get_model("audio", "AudioChannel")
    for channel in AudioChannel.objects.all():
        ids = list(channel.order or [])
        channel.queue = [{"k": k + 1, "t": t} for k, t in enumerate(ids)]
        channel.cur = min(channel.index, max(len(ids) - 1, 0))
        channel.source = channel.playlist.name if channel.playlist_id else ("Library" if ids else "")
        channel.save(update_fields=["queue", "cur", "source"])


